const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry Definition
    const moroto = ee.Geometry.Point([34.6667, 2.9167]); // Coordinates for Moroto, Uganda
    const roi = moroto.buffer(40 * 1000); // 40 km radius

    // 2. Date Definitions
    const startMonth = 8; // August
    const endMonth = 8;   // August
    const historicalStartYear = 1991;
    const historicalEndYear = 2010;
    const currentYear = 2023;

    // 3. Data Acquisition & Processing

    // --- Historical Average (1991-2010) using NOAA AVHRR Pathfinder V5 L3 NDVI ---
    let historicalCollection = ee.ImageCollection('NOAA/AVHRR_Pathfinder_V5_L3')
      .filter(ee.Filter.calendarRange(startMonth, endMonth, 'month'))
      .filter(ee.Filter.calendarRange(historicalStartYear, historicalEndYear, 'year'))
      .filterBounds(roi);

    if (historicalCollection.size().getInfo() === 0) {
      console.log("No AVHRR images found for the historical period (1991-2010) in August.");
      console.log("C1");
      return;
    }

    // Apply a simple quality filter (e.g., exclude quality > 64 for AVHRR, which indicates potential issues)
    // The AVHRR documentation suggests quality > 64 indicates cloud, snow, coast, or other problems.
    historicalCollection = historicalCollection.map(image =>
      image.updateMask(image.select('quality').lte(64))
    );

    const historicalNdvlImage = historicalCollection.select('NDVI').mean();

    // Check if the historical mean image is empty (all pixels masked out)
    const historicalPixelCount = historicalNdvlImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: 5000, // AVHRR resolution is ~8km, use a coarser scale for speed
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    if (historicalPixelCount === 0) {
      console.log("Historical images exist, but 0 valid pixels remain after quality masking.");
      console.log("C2");
      return;
    }

    const historicalNdvl = historicalNdvlImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: roi,
      scale: 5000,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    if (historicalNdvl === null || isNaN(historicalNdvl)) {
      console.log("Calculation of historical average NDVI failed (NaN/None).");
      console.log("C3");
      return;
    }

    // --- Current Period (August 2023) using MODIS MOD13A2 V6 NDVI ---
    // Note: AVHRR and MODIS are different sensors; direct comparison should acknowledge potential inter-sensor biases.
    let currentCollection = ee.ImageCollection('MODIS/061/MOD13A2')
      .filter(ee.Filter.calendarRange(startMonth, endMonth, 'month'))
      .filter(ee.Filter.calendarRange(currentYear, currentYear, 'year'))
      .filterBounds(roi);

    if (currentCollection.size().getInfo() === 0) {
      console.log("No MODIS images found for August 2023.");
      console.log("C1");
      return;
    }

    // Function to mask clouds in MODIS MOD13A2
    const modisCloudMask = (image) => {
      const qa = image.select('Detailed_QA');
      // Bits 0-1: MODLAND QA (0: good, 1: marginal, 2: snow/ice, 3: cloudy)
      const cloudState = qa.bitwiseAnd(3);
      const goodQuality = cloudState.eq(0); // Only good quality pixels
      return image.updateMask(goodQuality);
    };

    currentCollection = currentCollection.map(modisCloudMask);

    const currentNdvlImage = currentCollection.select('NDVI').mean();

    // Check if the current mean image is empty (all pixels masked out)
    const currentPixelCount = currentNdvlImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: 1000, // MODIS MOD13A2 resolution is 1km, use this scale
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    if (currentPixelCount === 0) {
      console.log("Current images exist, but 0 valid pixels remain after cloud masking.");
      console.log("C2");
      return;
    }

    const currentNdvl = currentNdvlImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: roi,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDVI').getInfo();

    if (currentNdvl === null || isNaN(currentNdvl)) {
      console.log("Calculation of current average NDVI failed (NaN/None).");
      console.log("C3");
      return;
    }

    // Scale NDVI values (AVHRR and MODIS NDVI typically range from -2000 to 10000, so divide by 10000)
    const scaledHistoricalNdvl = historicalNdvl / 10000;
    const scaledCurrentNdvl = currentNdvl / 10000;

    // 4. Comparison and Final Answer
    console.log(`Historical (1991-2010) August AVG NDVI: ${scaledHistoricalNdvl.toFixed(3)} (Pixels: ${historicalPixelCount})`);
    console.log(`2023 August AVG NDVI: ${scaledCurrentNdvl.toFixed(3)} (Pixels: ${currentPixelCount})`);

    if (scaledCurrentNdvl < scaledHistoricalNdvl) {
      console.log("A"); // Yes, lower
    } else {
      console.log("B"); // No, not lower
    }

  } catch (e) {
    console.error("An error occurred during analysis: ", e);
    console.log("D"); // General error or memory issue
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
